// A square inverse-circle alpha mask, shared by native and web crop previews.
const {writeFile} = require('node:fs/promises');
const {join} = require('node:path');
const sharp = require('sharp');

(async () => {
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024"><path fill="black" fill-rule="evenodd" d="M0 0H1024V1024H0Z M512 0A512 512 0 1 0 512 1024A512 512 0 1 0 512 0Z"/></svg>';
  const png = await sharp(Buffer.from(svg)).png().toBuffer();
  await writeFile(join(__dirname, '../src/ui/settings/photoCropMask.ts'),
    '// Generated by scripts/generate-photo-crop-mask.cjs.\n' +
    `export const photoCropMask = {uri: 'data:image/png;base64,${png.toString('base64')}'};\n`);
})().catch(error => {console.error(error); process.exitCode = 1;});
